```diff
diff --git a/staging/src/k8s.io/apimachinery/pkg/apis/meta/v1/unstructured/unstructured_list.go b/staging/src/k8s.io/apimachinery/pkg/apis/meta/v1/unstructured/unstructured_list.go
index 5028f5fb57a..0196f3f4dfe 100644
--- a/staging/src/k8s.io/apimachinery/pkg/apis/meta/v1/unstructured/unstructured_list.go
+++ b/staging/src/k8s.io/apimachinery/pkg/apis/meta/v1/unstructured/unstructured_list.go
@@ -45,7 +45,7 @@ func (u *UnstructuredList) IsList() bool { return true }
 
 func (u *UnstructuredList) EachListItem(fn func(runtime.Object) error) error {
 	for i := range u.Items {
-		if err := fn(&u.Items[i]); err != nil {
+		if err := fn(&Unstructured{Object: u.Items[i].Object}); err != nil {
 			return err
 		}
 	}
```

that's actually what Unstructured#EachListItem already does
